import assert from "node:assert/strict";
import test from "node:test";

import { barsDone, blocksUntil, capsuleMessage, decryptLetter, encryptLetter, fingerprintOk, isoZ, keyFromHash, nextAnniversary, openHeightEstimate, shortHash, spanText } from "./capsule.ts";

// Expected strings generated by api/capsule.py capsule_message.
const expected = [
  "unimap time capsule\nto: 18 岁的小满\nopen-at: 2044-10-16T00:00:00Z\nsha256: abababababababababababababababababababababababababababababababab\npublic: 女儿出生。\ntag: birth\ntime: 1760000000",
  "unimap time capsule\nto: me\nopen-at: 2027-01-15T08:00:00Z\nsha256: cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd\npublic: none\ntag: none\ntime: 1",
];

test("capsule message matches the API", () => {
  assert.equal(capsuleMessage("18 岁的小满", 2360188800, "ab".repeat(32), "女儿出生。", "birth", 1760000000), expected[0]);
  assert.equal(capsuleMessage("me", 1800000000, "cd".repeat(32), null, null, 1), expected[1]);
  assert.equal(isoZ(0), "1970-01-01T00:00:00Z");
});

test("blocks to the opening, at ten minutes a block", () => {
  assert.equal(blocksUntil(6000, 0), 10);
  assert.equal(blocksUntil(6001, 0), 11);
  assert.equal(blocksUntil(100, 200), 1); // past due: the next block
  assert.equal(openHeightEstimate(971_444, 600 * 946_556, 0), 971_444 + 946_556);
  assert.equal(blocksUntil(750, 0, 75), 10); // the demo's 75-second blocks
  assert.equal(spanText(946_556), "大约 18 年");
  assert.equal(spanText(6), "大约 1 小时");
  assert.equal(spanText(1, 75), "大约 1 分钟");
  assert.equal(barsDone(100, 100, 1000), 1);
  assert.equal(barsDone(100, 200, 100), 9);
  assert.equal(barsDone(100, 300, 0), 18);
});

test("spare key in the link fragment", () => {
  const k = "A".repeat(43);
  assert.equal(keyFromHash(`#k=${k}`), k);
  assert.equal(keyFromHash(`#x=1&k=${k}`), k);
  assert.equal(keyFromHash("#k=short"), null);
  assert.equal(shortHash("7f3a91c2" + "0".repeat(52) + "e04b"), "7f3a91c2…e04b");
});

test("next anniversary of a day", () => {
  const oct15_2026 = Date.UTC(2026, 9, 15) / 1000;
  assert.equal(nextAnniversary("2003-10-16", oct15_2026), "2026-10-16");
  assert.equal(nextAnniversary("2003-10-14", oct15_2026), "2027-10-14");
  assert.equal(nextAnniversary("2004-02-29", oct15_2026), "2028-02-29");
});

test("encrypt, decrypt and check the fingerprint", async () => {
  const sealed = await encryptLetter("小满：生日快乐。");
  assert.match(sealed.key, /^[A-Za-z0-9_-]{43}$/);
  assert.equal(await decryptLetter(sealed.ciphertext, sealed.key), "小满：生日快乐。");
  assert.ok(await fingerprintOk(sealed.ciphertext, sealed.fingerprint));
  const other = await encryptLetter("x");
  await assert.rejects(decryptLetter(sealed.ciphertext, other.key));
});
